Settings
NexT config file# WaveDrom tagwavedrom:  enable: true
Usage
&#123;% wavedrom %&#125;&#123;% endwavedrom %&#125;
Examples
&#123;% wavedrom %&#125;&#123; signal : [  &#123; name: &quot;clk&quot;,  wave: &quot;p......&quot; &#125;,  &#123; name: &quot;bus&quot;,  wave: &quot;x.34.5x&quot;,   data: &quot;head body tail&quot; &#125;,  &#123; name: &quot;wire&quot;, wave: &quot;0.1..0.&quot; &#125;,]&#125;&#123;% endwavedrom %&#125;

{ signal : [
  { name: "clk",  wave: "p......" },
  { name: "bus",  wave: "x.34.5x",   data: "head body tail" },
  { name: "wire", wave: "0.1..0." },
]}

&#123;% wavedrom %&#125;&#123; signal: [  &#123; name: &#x27;A&#x27;, wave: &#x27;01........0....&#x27;,  node: &#x27;.a........j&#x27; &#125;,  &#123; name: &#x27;B&#x27;, wave: &#x27;0.1.......0.1..&#x27;,  node: &#x27;..b.......i&#x27; &#125;,  &#123; name: &#x27;C&#x27;, wave: &#x27;0..1....0...1..&#x27;,  node: &#x27;...c....h..&#x27; &#125;,  &#123; name: &#x27;D&#x27;, wave: &#x27;0...1..0.....1.&#x27;,  node: &#x27;....d..g...&#x27; &#125;,  &#123; name: &#x27;E&#x27;, wave: &#x27;0....10.......1&#x27;,  node: &#x27;.....ef....&#x27; &#125;  ],  edge: [    &#x27;a~b t1&#x27;, &#x27;c-~a t2&#x27;, &#x27;c-~&gt;d time 3&#x27;, &#x27;d~-e&#x27;,    &#x27;e~&gt;f&#x27;, &#x27;f-&gt;g&#x27;, &#x27;g-~&gt;h&#x27;, &#x27;h~&gt;i some text&#x27;, &#x27;h~-&gt;j&#x27;  ],  config:&#123;skin:&#x27;lowkey&#x27;&#125;&#125;&#123;% endwavedrom %&#125;

{ signal: [
  { name: 'A', wave: '01........0....',  node: '.a........j' },
  { name: 'B', wave: '0.1.......0.1..',  node: '..b.......i' },
  { name: 'C', wave: '0..1....0...1..',  node: '...c....h..' },
  { name: 'D', wave: '0...1..0.....1.',  node: '....d..g...' },
  { name: 'E', wave: '0....10.......1',  node: '.....ef....' }
  ],
  edge: [
    'a~b t1', 'c-~a t2', 'c-~>d time 3', 'd~-e',
    'e~>f', 'f->g', 'g-~>h', 'h~>i some text', 'h~->j'
  ],
  config:{skin:'lowkey'}
}

&#123;% wavedrom %&#125;&#123;reg:[    &#123;bits: 7,  name: 0x07, attr: [      &#x27;VLxU,VLE zero-extended&#x27;,      &#x27;VLxU,VLE zero-extended, fault-only-first&#x27;,      &#x27;VLxU sign-extended&#x27;,      &#x27;VLxU sign-extended, fault-only-first&#x27;,    ]&#125;,    &#123;bits: 5,  name: &#x27;vd&#x27;, attr: &#x27;destination of load&#x27;, type: 2&#125;,    &#123;bits: 3,  name: &#x27;width&#x27;&#125;,    &#123;bits: 5,  name: &#x27;rs1&#x27;, attr: &#x27;base address&#x27;, type: 4&#125;,    &#123;bits: 5,  name: &#x27;lumop&#x27;, attr: [0, 16, 0, 16]&#125;,    &#123;bits: 1,  name: &#x27;vm&#x27;&#125;,    &#123;bits: 3,  name: &#x27;mop&#x27;, attr: [0, 0, 4, 4]&#125;,    &#123;bits: 3,  name: &#x27;nf&#x27;&#125;,]&#125;&#123;% endwavedrom %&#125;

{reg:[
    {bits: 7,  name: 0x07, attr: [
      'VLxU,VLE zero-extended',
      'VLxU,VLE zero-extended, fault-only-first',
      'VLxU sign-extended',
      'VLxU sign-extended, fault-only-first',
    ]},
    {bits: 5,  name: 'vd', attr: 'destination of load', type: 2},
    {bits: 3,  name: 'width'},
    {bits: 5,  name: 'rs1', attr: 'base address', type: 4},
    {bits: 5,  name: 'lumop', attr: [0, 16, 0, 16]},
    {bits: 1,  name: 'vm'},
    {bits: 3,  name: 'mop', attr: [0, 0, 4, 4]},
    {bits: 3,  name: 'nf'},
]}
